264	  // Note: status === "failed" means the ranking pipeline failed, NOT that the
265	  // job is closed for applications. We don't block applications on failed jobs.
266	  if (!jobLoading && (jobError || !job)) {
267	    return (
268	      <div className="min-h-screen bg-background flex flex-col">
269	        <ApplyHeader />
270	        <main className="flex-1 flex items-center justify-center px-4 py-16">
271	          <div className="w-full max-w-md text-center space-y-4">
272	            <div className="flex justify-center">
273	              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
274	                <Briefcase className="h-7 w-7 text-muted-foreground" />
275	              </div>
276	            </div>
277	            <h1 className="text-xl font-semibold">Job not found</h1>
278	            <p className="text-sm text-muted-foreground">
279	              This application link may have expired or the job no longer exists.
280	            </p>
281	            <Link
282	              to="/"
283	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
284	            >
285	              Back to Jobs
286	            </Link>
287	          </div>
288	        </main>
289	        <ApplyFooter />
290	      </div>
291	    );
292	  }
293	
294	  return (
295	    <div className="min-h-screen bg-background flex flex-col">
296	      <ApplyHeader />
297	
298	      <main className="flex-1 flex items-start justify-center px-4 py-10">
299	        <div className="w-full max-w-lg">
300	          {/* Job title */}
301	          <div className="mb-8 space-y-1">
302	            {jobLoading ? (
303	              <>
304	                <Skeleton className="h-7 w-64" />
305	                <Skeleton className="h-4 w-40 mt-2" />
