357	            {/* Email */}
358	            <div className="space-y-1.5">
359	              <Label htmlFor="apply-email">
360	                Email Address <span className="text-destructive">*</span>
361	              </Label>
362	              <Input
363	                id="apply-email"
364	                type="email"
365	                placeholder="jane@example.com"
366	                value={email}
367	                onChange={(e) => {
368	                  setEmail(e.target.value);
369	                  if (fieldErrors.email)
370	                    setFieldErrors((prev) => ({ ...prev, email: "" }));
