388	                id="apply-phone"
389	                type="tel"
390	                placeholder="+1 555 000 0000"
391	                value={phone}
392	                onChange={(e) => setPhone(e.target.value)}
393	                autoComplete="tel"
394	                disabled={submitting}
395	              />
396	            </div>
397	
398	            {/* Resume Upload */}
