404	                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
405	                  <button
406	                    type="button"
407	                    onClick={() => {
408	                      setResumeFile(null);
409	                      if (fileInputRef.current) fileInputRef.current.value = "";
