411	                    className="text-muted-foreground hover:text-destructive transition-colors"
412	                    aria-label="Remove resume"
413	                    disabled={submitting}
414	                  >
415	                    <X className="h-4 w-4" />
416	                  </button>
417	                </div>
418	              ) : (
419	                <div
