429	                      ? "border-primary bg-primary/5 scale-[1.01]"
430	                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
431	                  }`}
432	                  onDragOver={(e) => {
433	                    e.preventDefault();
434	                    setDragOver(true);
